import{_ as e,o as l,c as r,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const k=JSON.parse('{"title":"Ceph Orchestrator Meeting 2021-06-08","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2021-06-08","date":"2021-06-08T00:00:00.000Z","updated":"2021-06-09T00:00:00.000Z","tags":["Ceph","Orchestrator","Rook Manager","测试框架","集成"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-06-08.md","filePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-06-08.md","lastUpdated":1780459816000}'),o={name:"posts/2021/Ceph_Orchestrator_Meeting_2021-06-08.md"};function t(n,a,h,s,d,u){return l(),r("div",null,[...a[0]||(a[0]=[i('<h3 id="改进后的会议纪要" tabindex="-1">改进后的会议纪要 <a class="header-anchor" href="#改进后的会议纪要" aria-label="Permalink to &quot;改进后的会议纪要&quot;">​</a></h3><h4 id="会议主题-rook-manager-模块讨论" tabindex="-1">会议主题：Rook Manager 模块讨论 <a class="header-anchor" href="#会议主题-rook-manager-模块讨论" aria-label="Permalink to &quot;会议主题：Rook Manager 模块讨论&quot;">​</a></h4><h4 id="会议时间-本周协调会议" tabindex="-1">会议时间：本周协调会议 <a class="header-anchor" href="#会议时间-本周协调会议" aria-label="Permalink to &quot;会议时间：本周协调会议&quot;">​</a></h4><h4 id="参会人员-全体成员" tabindex="-1">参会人员：全体成员 <a class="header-anchor" href="#参会人员-全体成员" aria-label="Permalink to &quot;参会人员：全体成员&quot;">​</a></h4><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>Gherkin 语言实现介绍</strong></p><ul><li>Aaron 介绍了 Gherkin 语言，一种测试场景定义语言，使用自然语言定义系统行为，使非技术人员也能参与测试。</li><li>使用 Given、When 等关键字运行场景并断言结果，例如登录节点执行命令并验证版本匹配。</li><li>讨论了使用 kcli 和虚拟机创建测试环境，以及 Behave 框架和 Gherkin 语言在测试场景中的应用。</li></ul></li><li><p><strong>测试框架集成</strong></p><ul><li>讨论使用 kcli 和虚拟机快速创建测试环境。</li><li>依赖于 Python 的 Behave 框架，使用 Gherkin 语言定义测试场景并通过 Python 实现执行。</li><li>讨论了项目文件结构和在社区中实施此项目的方案。</li></ul></li><li><p><strong>Rook Manager 模块状态与未来方向</strong></p><ul><li>讨论在 Jenkins 中集成测试框架，确保测试自动验证。</li><li>讨论Rook在裸机部署中的适用性以及设备管理。</li><li>确定需要解决的关键问题，如OSD创建和块数据库设备管理。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>确定在 Jenkins 中集成测试框架。</li><li>确认需要新的接口来处理 Kubernetes 环境中的 PV 和动态供应。</li><li>确定需要与 Rook 和 LSO 相关人员进行进一步讨论，以确定在不同环境中使用 Rook。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>Aaron 将继续推进 Gherkin 语言的实现和测试框架的集成。</li><li>确定与 Rook 和 LSO 相关人员的会议，讨论在不同环境中使用 Rook。</li><li>Joseph 将继续调查 Rook 中的 orange ls 和 rgps 命令问题，并确保这些命令在沙箱环境中正常工作。</li></ul><h4 id="其他讨论点" tabindex="-1">其他讨论点： <a class="header-anchor" href="#其他讨论点" aria-label="Permalink to &quot;其他讨论点：&quot;">​</a></h4><ul><li>讨论了 Rook 在不同环境中的使用，特别是在 OpenShift 中。</li><li>确认了需要进一步讨论如何在不同环境中管理设备和 OSD。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>会议在确认下一步行动计划后结束。</li></ul><h4 id="下次会议" tabindex="-1">下次会议： <a class="header-anchor" href="#下次会议" aria-label="Permalink to &quot;下次会议：&quot;">​</a></h4><ul><li>下周继续讨论 Rook Manager 模块的进展和其他相关议题。</li></ul>',16)])])}const p=e(o,[["render",t]]);export{k as __pageData,p as default};
